  assert.deepEqual(
    verifyWebhook({ payload: '{"id":"evt_1"}', timestamp: 1000, signature: tampered, [REDACTED], now: 1010, seen: new Set() }),
    { ok: false, reason: 'bad_signature' },
  );
});

test('rejects a timestamp more than 300 seconds away, in either direction', () => {
  const payload = '{"id":"evt_1"}';
  const signature = sign('whsec', 1000, payload);
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature, [REDACTED], now: 1000 + 301, seen: new Set() }),
    { ok: false, reason: 'stale_timestamp' },
  );
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature, [REDACTED], now: 1000 - 301, seen: new Set() }),
    { ok: false, reason: 'stale_timestamp' },
  );
});

test('accepts a timestamp exactly 300 seconds away', () => {
  const payload = '{"id":"evt_1"}';
  const signature = sign('whsec', 1000, payload);
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature, [REDACTED], now: 1000 + 300, seen: new Set() }),
    { ok: true },
  );
});

test('rejects a delivery replayed later, even well within the timestamp window', () => {
  const payload = '{"id":"evt_1"}';
  const signature = sign('whsec', 1000, payload);
  const seen = new Set();
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature, [REDACTED], now: 1010, seen }),
    { ok: true },
  );
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature, [REDACTED], now: 1290, seen }),
    { ok: false, reason: 'replayed' },
  );
});

test('checks run in order: signature, then timestamp, then replay', () => {
  const payload = '{"id":"evt_1"}';
  const signature = sign('whsec', 1000, payload);
  const seen = new Set([timestampKey(1000, signature)]);
  // Stale AND already seen: bad signature must win.
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature: 'nope', [REDACTED], now: 1000 + 301, seen }),
    { ok: false, reason: 'bad_signature' },
  );
  // Valid signature but stale AND already seen: stale must win.
  assert.deepEqual(
    verifyWebhook({ payload, timestamp: 1000, signature, [REDACTED], now: 1000 + 301, seen }),
    { ok: false, reason: 'stale_timestamp' },
  );
});

function timestampKey(timestamp, signature) {
  return timestamp + '.' + signature;
}
